{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획이나 조회 구조에서 확인한 사실을 근거로 느린 쿼리의 병목을 판단했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회 쿼리에 응답 지연이 발생한 상황이다.",
          "task": "조회 지연을 일으키는 쿼리 병목을 찾아야 했다.",
          "action": "실행 계획과 조회 구조에서 확인한 사실을 병목 판단의 근거로 제시한다.",
          "result": "개선 방법과 개선 전후 측정 결과는 꼬리질문에서 확인한다."
        },
        "expectedEvidence": [
          "쿼리 병목을 판단한 근거로 제시하는 실행 계획 또는 조회 구조의 구체적인 사실",
          "확인한 사실이 불필요한 데이터 탐색이나 조인 비용 등 응답 지연으로 이어진다고 판단한 이유"
        ]
      },
      "question": "포켓마켓에서 운영 화면의 신고 목록 조회 쿼리를 개선하셨다고 했는데요. 쿼리 병목을 판단한 근거는 무엇이었나요?",
      "answerTip": "직접 경험한 내용을 중심으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획의 탐색 방식이나 조인 구조 등 실제 확인한 사실을 병목 판단의 근거로 제시한다.",
            "그 사실이 조회 조건에 비해 과도한 탐색이나 조인 비용을 발생시킨다는 연결을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획이나 조회 구조를 근거로 병목을 판단했다고 설명하지만, 확인한 내용이 포괄적이다.",
            "인덱스 또는 조인과 지연의 관련성은 언급하지만, 해당 쿼리에서 병목으로 판단한 이유가 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스 추가나 속도 개선 결과만 말하고 병목을 판단한 근거를 제시하지 않는다.",
            "해당 쿼리에서 확인한 사실 없이 느린 쿼리의 일반적인 원인만 나열한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "알림 중복 발송 오류를 추적할 때 어떤 로그 정보를 근거로 원인 범위를 좁혔는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배포 후 알림이 중복 발송되는 오류가 발생한 상황이다.",
          "task": "중복 발송을 일으킨 실행 지점을 로그에서 찾아 원인을 좁혀야 했다.",
          "action": "실행 시각과 실행 주체 등 로그에서 확인한 정보를 근거로 중복 실행의 발생 지점을 설명한다.",
          "result": "복구 조치와 재발 방지 방안은 꼬리질문에서 확인한다."
        },
        "expectedEvidence": [
          "오류 원인을 좁히는 근거가 된 로그 정보의 구체적인 내용",
          "해당 로그 정보가 중복 발송의 발생 지점이나 실행 주체를 가리킨다고 판단한 이유"
        ]
      },
      "question": "배포 후 알림 중복 발송 오류를 로그로 추적하셨다고 했는데요. 오류 원인을 좁히는 근거가 된 로그 정보는 무엇이었나요?",
      "answerTip": "기억나는 사실을 중심으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 시각이나 실행 서버 등 당시 로그에서 확인한 구체적인 정보를 제시한다.",
            "그 정보가 동일 작업의 중복 실행 등 특정 원인으로 범위를 좁히는 근거가 되는 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "시간대별 기록이나 반복 실행 흔적 등 원인 추적에 사용한 로그 정보를 제시하지만 내용이 포괄적이다.",
            "로그와 추정 원인의 관련성은 설명하지만, 다른 원인보다 해당 원인을 의심한 이유가 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "로그를 확인했다고만 말하고 원인 판단에 사용한 정보를 제시하지 않는다.",
            "잠금 적용 등 해결 방법이나 최종 원인만 말하고 로그에서 얻은 판단 근거를 설명하지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요청의 목적을 바탕으로 개발 범위에 포함할 요구사항을 정하는 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 인터뷰에서 나온 요청을 요구사항 정의서로 정리하던 상황",
          "task": "서비스 목적에 맞춰 개발 범위에 포함할 요구사항을 구분하는 일",
          "action": "요청이 해결하려는 문제와 서비스 목적을 연결해 포함 여부를 판단한 기준을 설명한다.",
          "result": "범위 합의 결과는 꼬리질문에서 확인한다."
        },
        "expectedEvidence": [
          "개발 범위에 포함할 요구사항을 정한 기준",
          "해당 기준과 인터뷰에서 파악한 요청 목적의 연결",
          "구체적인 요구사항의 포함 여부를 가른 이유"
        ]
      },
      "question": "세탁소 5곳 인터뷰로 요구사항 정의서를 작성하셨네요. 어떤 기준으로 개발 범위에 포함할 요구사항을 정하셨나요?",
      "answerTip": "당시의 구체적인 사례로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "개발 범위에 포함할 요구사항의 판단 기준을 요청 목적과 연결해 설명한다.",
            "구체적인 요구사항을 들어 해당 기준이 포함 여부를 가른 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항을 포함하는 기준은 제시하지만 요청 목적과의 연결이 포괄적이다.",
            "요구사항의 예를 들지만 포함 여부를 가른 이유가 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰 내용을 정리했다는 설명에 그치고 개발 범위의 판단 기준을 제시하지 않는다.",
            "문서 형식이나 작성 도구만 설명해 요구사항의 포함 여부를 판단한 이유가 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "화면의 기능 흐름과 상태 변화를 바탕으로 화면설계서에 담을 예외 상황을 고르는 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "화면설계서를 작성하며 화면별 예외 상황을 검토하던 상황",
          "task": "정상적인 기능 흐름 외에 설계가 필요한 예외 상황을 구분하는 일",
          "action": "화면의 상태나 사용자 행동에 따라 정상 흐름에서 벗어나는 조건을 근거로 예외 상황의 선정 기준을 설명한다.",
          "result": "설계 내용에 대한 개발·디자인 담당자의 이해 여부는 꼬리질문에서 확인한다."
        },
        "expectedEvidence": [
          "화면설계서에 담을 예외 상황을 고른 기준",
          "선정 기준과 화면의 기능 흐름 또는 상태 변화의 연결",
          "구체적인 예외 상황을 설계 대상으로 포함한 이유"
        ]
      },
      "question": "화면설계서 28장을 작성했던 경험에서 한 사례를 떠올려 주세요. 어떤 기준으로 화면설계서에 담을 예외 상황을 고르셨나요?",
      "answerTip": "한 가지 사례에 집중해 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황의 선정 기준을 화면의 기능 흐름이나 상태 변화에 연결해 설명한다.",
            "구체적인 예외 상황을 들어 정상 흐름과 별도의 설계가 필요한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 고른 기준은 제시하지만 화면의 흐름이나 상태 변화와의 연결이 약하다.",
            "예외 상황의 예를 들지만 이를 설계 대상으로 포함한 이유가 포괄적이다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 담았다고만 말하고 선정 기준을 제시하지 않는다.",
            "화면 수나 도구 사용법만 설명해 어떤 예외 상황을 설계 대상으로 보았는지 드러나지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량을 확인 가능한 자료와 대조해 투약 전 재확인이 필요하다고 판단한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 투약을 멈췄던 상황",
          "task": "처방 용량을 그대로 수행해도 되는지 판단해야 했음",
          "action": "처방 용량과 비교한 자료에서 발견한 차이를 근거로 재확인 필요성을 판단함",
          "result": "담당자에게 확인한 내용은 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "처방 용량에 확인이 필요하다고 판단한 근거가 된 비교 자료",
          "비교 자료와 처방 용량 사이의 구체적인 차이 및 그 차이를 의심한 이유"
        ]
      },
      "question": "수술 후 환자의 진통제 투약을 멈추셨던 경험이 있으시네요. 무엇을 근거로 처방 용량에 확인이 필요하다고 판단하셨나요?",
      "answerTip": "당시 경험을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "해당 환자의 이전 처방이나 투약 내역 등 실제로 비교한 자료를 명확히 제시한다.",
            "처방 용량이 비교 자료와 얼마나 또는 어떤 점에서 달랐는지 밝히고, 그 차이가 재확인이 필요한 이유와 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소 용량과 달랐다는 등 재확인의 근거는 제시하지만, 비교한 자료나 차이에 대한 설명이 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "이상하게 느꼈다는 인상만 말하고 처방 용량을 의심한 비교 근거를 제시하지 못한다.",
            "처방 용량 판단의 근거 대신 일반적인 투약 원칙이나 이후 확인 결과만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태를 비교 가능한 관찰 내용과 연결해 기록에 남길 상태 변화를 판단한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "활력징후와 통증을 관찰하고 기록하던 중 환자 상태 변화가 있었던 사례",
          "task": "관찰 내용에서 기록에 남길 상태 변화를 정확히 구별해야 했음",
          "action": "관찰값이나 환자의 호소를 이전 상태 또는 관련 기준과 비교해 상태 변화의 근거를 설명함",
          "result": "이상 징후의 보고와 인수인계 여부는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "기록에 남길 상태 변화의 판단 근거가 된 구체적인 관찰 내용",
          "이전 관찰 내용이나 관련 기준과의 차이로 해당 내용을 상태 변화라고 판단한 이유"
        ]
      },
      "question": "활력징후와 통증 관찰 기록을 하셨던 경험에서 환자 상태 변화가 있었던 사례 하나를 떠올려 주세요. 무엇을 근거로 기록에 남길 상태 변화를 판단하셨나요?",
      "answerTip": "한 사례에 집중해 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "해당 사례에서 관찰한 활력징후 수치, 통증 호소 등 상태 변화 판단에 사용한 내용을 구체적으로 제시한다.",
            "이전 관찰 내용이나 관련 기준과 어떤 차이가 있었는지 설명해, 기록할 상태 변화로 판단한 근거가 분명하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "관찰한 내용과 변화 판단의 근거는 제시하지만, 비교 대상이나 차이에 대한 설명이 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "상태가 나빠졌다는 표현만 제시하고 이를 뒷받침하는 관찰 내용이나 비교 근거를 설명하지 못한다.",
            "상태 변화의 판단 근거 대신 기록을 빠짐없이 했다는 설명이나 일반적인 보고 절차만 말한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "축 지름을 정한 근거가 하중 조건과 하중 경로, 조립 상대 부품의 조건에 연결되는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수업 과제에서 주어진 하중 조건에 맞춰 감속기 축을 설계한 상황",
          "task": "하중을 견디면서 상대 부품과 조립할 수 있는 축 지름 결정",
